let raw = $input.item.json.output || "";
raw = raw.replace(/```json/g, "").replace(/```/g, "").trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { intent: "UNSUPPORTED", sql: "NONE", reasoning: "Failed to parse model output." };
}

const sql = (parsed.sql || "").trim();
const blocked = /\b(DROP|DELETE|UPDATE|ALTER|INSERT|TRUNCATE|CREATE|GRANT|REVOKE)\b/i;

if (blocked.test(sql)) {
  parsed = { intent: "UNSUPPORTED", sql: "NONE", reasoning: "Blocked unsafe SQL." };
}

return {
  json: {
    intent: parsed.intent,
    sql: parsed.sql === "NONE" ? "NONE" : sql,
    reasoning: parsed.reasoning,
    original_query: $("1. Webhook Trigger").item.json.body.query
  }
};

const rows=$input.all().map(i=>i.json);

const formatted=rows.map(r=>{

let obj={};

for(const k in r){

obj[k]=typeof r[k]=="number"

?Number(r[k].toFixed(2))

:r[k];

}

return obj;

});

return{

json:{

intent:"EDA",

summary:formatted

}

};

const rows=$input.all().slice(0,10);

const filtered=rows.map(r=>({

BALANCE:r.json.BALANCE,

PURCHASES:r.json.PURCHASES,

CREDIT_LIMIT:r.json.CREDIT_LIMIT,

PAYMENTS:r.json.PAYMENTS

}));

return{

json:{

intent:"SEGMENTATION",

sample_size:filtered.length,

customers:filtered

}

};

const row=$input.first().json;

let cleaned={};

for(const k in row){

if(

row[k]!==0

&&

row[k]!==null

&&

row[k]!==""

){

cleaned[k]=typeof row[k]=="number"

?Number(row[k].toFixed(2))

:row[k];

}

}

return{

json:{

intent:"EXPLAINABILITY",

customer:cleaned

}

};

const rows=$input.all().map(i=>i.json);

const cleaned=rows
.slice(0,10)
.map(r=>{

let obj={};

for(const k in r){

if(r[k]===null) continue;

if(r[k]==="") continue;

if(typeof r[k]==="number")
obj[k]=Number(r[k].toFixed(2));

else
obj[k]=r[k];

}

return obj;

});

return{

json:{

intent:"DIRECT_QUERY",

status:"SUCCESS",

rows:cleaned,

record_count:cleaned.length

}

};

